using UnityEngine;
using UnityEditor;
using System;
using System.IO;
using System.Text;
using ConRoi.Investigation.V36;
using Object = UnityEngine.Object;

namespace Unity.AI.Assistant.Agent.Dynamic.Extension.Editor
{
    internal class CommandScript : IRunCommand
    {
        public void Execute(ExecutionResult r)
        {
            if (!EditorApplication.isPlaying)
                throw new Exception("Play required");
            var s = Object.FindFirstObjectByType<InvestigationSession>();
            if (!s.data.returnedToWorkshop)
                throw new Exception("Controller route must finish first");
            s.SaveDirectoryOverride = Path.GetFullPath("Test/KetQua/investigation_r102/visual-profile");
            var ids = new[]{"release", "help", "hold", "hook", "wedge", "after"};
            int phase = -1;
            bool started = false;
            double start = EditorApplication.timeSinceStartup;
            float last = -1;
            var log = new StringBuilder("Controlled game illustration playback; API opens pages/selects cases. Silent. Not controller movement evidence.\n");
            s.Acquire("clip");
            s.OpenPage("clip");
            s.UpdateClip();
            Action<string> shot = name => ScreenCapture.CaptureScreenshot("Test/BangChung/investigation_r102/" + name + ".png");
            EditorApplication.CallbackFunction update = null;
            update = () =>
            {
                if (!EditorApplication.isPlaying)
                {
                    EditorApplication.update -= update;
                    return;
                }

                float t = (float)(EditorApplication.timeSinceStartup - start);
                if (phase == -1)
                {
                    if (!started && t > .5f)
                    {
                        var w = EditorWindow.GetWindow(Type.GetType("UnityEditor.GameView,UnityEditor"));
                        var p = new Vector2(1200, 560);
                        w.SendEvent(new Event{type = EventType.MouseDown, button = 0, mousePosition = p});
                        w.SendEvent(new Event{type = EventType.MouseUp, button = 0, mousePosition = p});
                        started = true;
                    }

                    foreach (float at in new[]{1.5f, 3.7f, 5.3f, 8.2f})
                        if (last < at && t >= at)
                            shot("clip-" + at.ToString("F1", System.Globalization.CultureInfo.InvariantCulture));
                    if (t >= 11)
                    {
                        log.AppendLine("CLIP watched before=" + s.data.clipBeforeSeen + " event=" + s.data.clipEventSeen);
                        s.OpenPage("reconstruction");
                        phase = 0;
                        start = EditorApplication.timeSinceStartup;
                        s.StartTrial(ids[phase]);
                        last = -1;
                        return;
                    }
                }
                else
                {
                    foreach (float at in new[]{1f, 4f, 7f, 10.2f})
                        if (last < at && t >= at)
                            shot("trial-" + ids[phase] + "-" + at.ToString("F1", System.Globalization.CultureInfo.InvariantCulture));
                    if (t >= 11)
                    {
                        log.AppendLine(ids[phase] + " " + s.TrialReport);
                        phase++;
                        if (phase >= ids.Length)
                        {
                            EditorApplication.update -= update;
                            s.Save();
                            File.WriteAllText("Test/KetQua/investigation_r102/visual-playback.txt", log.ToString());
                            return;
                        }

                        start = EditorApplication.timeSinceStartup;
                        s.StartTrial(ids[phase]);
                        last = -1;
                        return;
                    }
                }

                last = t;
            };
            EditorApplication.update += update;
            r.Log("Started real-time clip + six model cases (API selection), 77s. Screens and video reviewed separately.");
        }
    }
}

